const std::vector<PublicLeague> publicLeagues={
 {"E0","Premier League","England"},{"E1","Championship","England"},{"E2","League One","England"},{"E3","League Two","England"},{"EC","National League","England"},
 {"SC0","Premiership","Scotland"},{"SC1","Championship","Scotland"},{"SC2","League One","Scotland"},{"SC3","League Two","Scotland"},
 {"SP1","La Liga","Spain"},{"SP2","Segunda Division","Spain"},{"I1","Serie A","Italy"},{"I2","Serie B","Italy"},{"F1","Ligue 1","France"},{"F2","Ligue 2","France"},
 {"D1","Bundesliga","Germany"},{"D2","2. Bundesliga","Germany"},{"N1","Eredivisie","Netherlands"},{"B1","Pro League","Belgium"},{"P1","Primeira Liga","Portugal"},{"T1","Super Lig","Turkey"},{"G1","Super League","Greece"}};
static int value(const std::string& s){if(s.empty())return -1;try{size_t used=0;int n=std::stoi(s,&used);return used==s.size()&&n>=0&&n<256?n:-1;}catch(...){return -1;}}
static int parseMatchCsv(Database& db,const std::string& raw,int league,const std::string& country,const std::string& wanted,int provider,Job& job){
    auto table=parseCsv(raw);if(table.size()<2)throw std::runtime_error("Provider returned no CSV rows");std::map<std::string,size_t> columns;for(size_t i=0;i<table[0].size();++i)columns[table[0][i]]=i;
    for(auto k:{"Date","HomeTeam","AwayTeam"})if(!columns.count(k))throw std::runtime_error("CSV is missing required column "+std::string(k));
    std::map<std::string,int> teams;auto team=[&](const std::string& n){if(!teams.count(n))teams[n]=db.team(provider,country+":"+n,n);return teams[n];};int count=0;
    db.exec("START TRANSACTION");try{for(size_t i=1;i<table.size();++i){if(i%100==0)job.check();auto& row=table[i];auto get=[&](const char* k){auto it=columns.find(k);return it!=columns.end()&&it->second<row.size()?row[it->second]:std::string();};if(columns.count("Div")&&!wanted.empty()&&get("Div")!=wanted)continue;if(get("HomeTeam").empty()||get("AwayTeam").empty())continue;
            Match m;try{m.date=csvDate(get("Date"));}catch(...){continue;}if(m.date<yearsAgo(5))continue;int year=std::stoi(m.date.substr(0,4)),month=std::stoi(m.date.substr(5,2));m.season=month>=7?year:year-1;m.league=league;m.home=team(get("HomeTeam"));m.away=team(get("AwayTeam"));
            const char* hc[]={"FTHG","HC","HY","HR","HST"};const char* ac[]={"FTAG","AC","AY","AR","AST"};for(int k=0;k<5;++k){m.h[k]=value(get(hc[k]));m.a[k]=value(get(ac[k]));}m.status=m.h[0]>=0&&m.a[0]>=0?"FT":"NS";db.upsertMatch(m,provider);++count;
        }db.exec("COMMIT");}catch(...){db.exec("ROLLBACK");throw;}return count;
}
void importPublic(Database& db,const std::string& code,Job& job,bool network){
    auto it=std::find_if(publicLeagues.begin(),publicLeagues.end(),[&](auto& l){return code==l.key;});if(it==publicLeagues.end())throw std::runtime_error("Unknown public league code");int league=db.league(0,it->key,it->name,it->country),year=std::stoi(today().substr(0,4));int imported=0,failed=0;
    for(int s=year-5;s<=year;++s){job.check();char season[8];snprintf(season,sizeof(season),"%02d%02d",s%100,(s+1)%100);std::string filename=std::string(season)+"_"+code+".csv";auto path=fs::path("data/public_cache")/filename;job.message("Importing "+code+" "+season);std::string raw;
        try{if(network){raw=httpGet("https://football-data.co.uk/mmz4281/"+std::string(season)+"/"+code+".csv");writeFile(path,raw);}else if(fs::exists(path))raw=readFile(path);else continue;std::string key="public-v2:"+filename;
            auto same=db.query("SELECT row_count FROM import_state WHERE source_key="+db.quote(key)+" AND content_hash=UNHEX(SHA2("+db.quote(raw)+",256))");if(same.empty()){int n=parseMatchCsv(db,raw,league,it->country,code,0,job);imported+=n;db.exec("REPLACE INTO import_state(source_key,content_hash,row_count,note) VALUES("+db.quote(key)+",UNHEX(SHA2("+db.quote(raw)+",256)),"+std::to_string(n)+",'Public CSV; player/lineup data not supplied')");}}
        catch(const std::exception&e){if(job.cancel)throw;++failed;job.message("Unavailable season "+std::string(season)+": "+e.what());}job.progress=double(s-(year-5)+1)/7;
    }
    job.check();try{fs::path path="data/public_cache/fixtures.csv";std::string raw;if(network){raw=httpGet("https://football-data.co.uk/fixtures.csv");writeFile(path,raw);}else if(fs::exists(path))raw=readFile(path);if(!raw.empty())imported+=parseMatchCsv(db,raw,league,it->country,code,0,job);}catch(const std::exception&e){if(job.cancel)throw;++failed;}
    job.progress=1;job.message(code+": "+std::to_string(imported)+" rows imported/updated; "+std::to_string(failed)+" unavailable requests. Missing stats remain NULL.");
}
void importCustomCsv(Database& db,const fs::path& path,const std::string& leagueName,Job& job){if(leagueName.empty())throw std::runtime_error("Enter a league name");int id=db.league(2,leagueName,leagueName,"Custom");int n=parseMatchCsv(db,readFile(path),id,leagueName,"",2,job);job.message("Custom CSV: "+std::to_string(n)+" matches imported");job.progress=1;}

class Api {
    const Settings& settings;Job& job;int limit,used=0;
public:
    Api(const Settings& s,Job& j,int n):settings(s),job(j),limit(n){if(s.apiKey.empty())throw std::runtime_error("Add an API-Football key in Settings for worldwide/player coverage.");}
    bool room()const{return used<limit;}
    json get(const std::string& path){job.check();if(!room())throw std::runtime_error("Request budget reached; import is resumable.");if(used)for(int elapsed=0;elapsed<settings.apiDelayMs;elapsed+=100){job.check();std::this_thread::sleep_for(std::chrono::milliseconds(100));}++used;job.message("API request "+std::to_string(used)+" / "+std::to_string(limit)+": "+path.substr(0,100));
        auto j=json::parse(httpGet("https://v3.football.api-sports.io/"+path,"x-apisports-key: "+settings.apiKey+"\r\n"));if(j.contains("errors")&&!j["errors"].empty())throw std::runtime_error("API-Football reported an error: check your key, plan, historical coverage and quota.");if(!j.contains("response")||!j["response"].is_array())throw std::runtime_error("Unexpected API response");return j;}
};
static int jint(const json& j,const char* key,int missing=-1){if(!j.is_object()||!j.contains(key)||j[key].is_null())return missing;try{if(j[key].is_number())return j[key].get<int>();return std::stoi(j[key].get<std::string>());}catch(...){return missing;}}
static std::string jstr(const json& j,const char* k,const std::string& fallback=""){return j.is_object()&&j.contains(k)&&j[k].is_string()?j[k].get<std::string>():fallback;}
static std::string sqlnum(int n){return n<0?"NULL":std::to_string(n);}
static int apiPlayer(Database& db,const json& p){int id=jint(p,"id");if(id<0)return 0;db.exec("INSERT INTO player(provider,external_id,name) VALUES(1,"+std::to_string(id)+","+db.quote(jstr(p,"name","Unknown"))+") ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id),name=VALUES(name)");return int(db.insertId());}
void importApiCatalog(Database& db,const Settings& s,Job& job){Api api(s,job,1);auto j=api.get("leagues");for(auto& x:j["response"]){job.check();if(!x.contains("league"))continue;db.league(1,std::to_string(jint(x["league"],"id")),jstr(x["league"],"name"),x.contains("country")?jstr(x["country"],"name"):"World");}job.progress=1;job.message("Worldwide league catalog loaded. Season/event coverage depends on the provider plan.");}
static void lineups(Database& db,long long fixture,const json& response){for(auto& group:response){if(!group.contains("team"))continue;int tid=db.team(1,std::to_string(jint(group["team"],"id")),jstr(group["team"],"name"));for(auto key:{"startXI","substitutes"})if(group.contains(key)&&group[key].is_array())for(auto& entry:group[key]){if(!entry.contains("player"))continue;auto p=entry["player"];int pid=apiPlayer(db,p);if(!pid)continue;db.exec("INSERT INTO appearance(fixture_id,team_id,player_id,starter,position,shirt) VALUES("+std::to_string(fixture)+","+std::to_string(tid)+","+std::to_string(pid)+","+(std::string(key)=="startXI"?"1":"0")+","+db.quote(jstr(p,"pos"))+","+sqlnum(jint(p,"number"))+") ON DUPLICATE KEY UPDATE starter=VALUES(starter),position=VALUES(position),shirt=VALUES(shirt)");}}}
static void players(Database& db,long long fixture,const json& response){for(auto& group:response){if(!group.contains("team")||!group.contains("players"))continue;int tid=db.team(1,std::to_string(jint(group["team"],"id")),jstr(group["team"],"name"));for(auto& entry:group["players"]){int pid=apiPlayer(db,entry["player"]);if(!pid||!entry.contains("statistics")||entry["statistics"].empty())continue;auto s=entry["statistics"][0];auto obj=[&](const char* key){return s.contains(key)&&s[key].is_object()?s[key]:json::object();};auto games=obj("games"),goals=obj("goals"),shots=obj("shots"),passes=obj("passes"),tackles=obj("tackles"),cards=obj("cards");std::string starter="NULL";if(games.contains("substitute")&&games["substitute"].is_boolean())starter=games["substitute"].get<bool>()?"0":"1";
            std::ostringstream q;q<<"INSERT INTO appearance(fixture_id,team_id,player_id,starter,position,minutes,goals,assists,shots,shots_on,passes,tackles,yellow,red) VALUES("<<fixture<<","<<tid<<","<<pid<<","<<starter<<","<<db.quote(jstr(games,"position"));for(int n:{jint(games,"minutes"),jint(goals,"total"),jint(goals,"assists"),jint(shots,"total"),jint(shots,"on"),jint(passes,"total"),jint(tackles,"total"),jint(cards,"yellow"),jint(cards,"red")})q<<","<<sqlnum(n);q<<") ON DUPLICATE KEY UPDATE starter=COALESCE(VALUES(starter),starter),position=VALUES(position),minutes=COALESCE(VALUES(minutes),minutes),goals=VALUES(goals),assists=VALUES(assists),shots=VALUES(shots),shots_on=VALUES(shots_on),passes=VALUES(passes),tackles=VALUES(tackles),yellow=VALUES(yellow),red=VALUES(red)";db.exec(q.str());if(jint(games,"minutes")>=0)db.exec("UPDATE appearance SET minutes_source=1 WHERE fixture_id="+std::to_string(fixture)+" AND player_id="+std::to_string(pid));
            std::string rating=games.contains("rating")&&!games["rating"].is_null()?(games["rating"].is_string()?games["rating"].get<std::string>():games["rating"].dump()):"";if(!rating.empty())try{double n=std::stod(rating);if(n>=0&&n<=10)db.exec("UPDATE appearance SET rating="+std::to_string(n)+" WHERE fixture_id="+std::to_string(fixture)+" AND player_id="+std::to_string(pid));}catch(...){}}
    }}
static void statistics(Database& db,const Match& match,const json& response){for(auto& group:response){if(!group.contains("team")||!group.contains("statistics"))continue;int tid=db.team(1,std::to_string(jint(group["team"],"id")),jstr(group["team"],"name"));std::map<std::string,std::string> val;for(auto& x:group["statistics"]){if(!x.contains("value")||x["value"].is_null())continue;val[jstr(x,"type")]=x["value"].is_string()?x["value"].get<std::string>():x["value"].dump();}
        auto number=[&](const std::string& k){if(!val.count(k))return std::string("NULL");try{double n=std::stod(val[k]);if(n>=0&&n<10000)return std::to_string(n);}catch(...){}return std::string("NULL");};
        bool home=tid==match.home;if((tid==match.home||tid==match.away)&&match.status=="FT"){std::string suffix=home?"h":"a";db.exec("UPDATE fixture SET c"+suffix+"="+number("Corner Kicks")+",y"+suffix+"="+number("Yellow Cards")+",r"+suffix+"="+number("Red Cards")+" WHERE id="+std::to_string(match.id));}
        db.exec("INSERT INTO team_match_extra(fixture_id,team_id,shots,shots_on,possession,xg,fouls,offsides,saves,passes) VALUES("+std::to_string(match.id)+","+std::to_string(tid)+","+number("Total Shots")+","+number("Shots on Goal")+","+number("Ball Possession")+","+number("expected_goals")+","+number("Fouls")+","+number("Offsides")+","+number("Goalkeeper Saves")+","+number("Total passes")+") ON DUPLICATE KEY UPDATE shots=COALESCE(VALUES(shots),shots),shots_on=COALESCE(VALUES(shots_on),shots_on),possession=COALESCE(VALUES(possession),possession),xg=COALESCE(VALUES(xg),xg),fouls=COALESCE(VALUES(fouls),fouls),offsides=COALESCE(VALUES(offsides),offsides),saves=COALESCE(VALUES(saves),saves),passes=COALESCE(VALUES(passes),passes)");}}
static void events(Database& db,long long fixture,const json& response){db.exec("DELETE FROM match_event WHERE fixture_id="+std::to_string(fixture));int i=0;for(auto& x:response){int pid=x.contains("player")?apiPlayer(db,x["player"]):0;int tid=x.contains("team")?db.team(1,std::to_string(jint(x["team"],"id")),jstr(x["team"],"name")):0;auto time=x.value("time",json::object());db.exec("INSERT INTO match_event(fixture_id,seq,team_id,player_id,minute,extra,type,detail) VALUES("+std::to_string(fixture)+","+std::to_string(i++)+","+(tid?std::to_string(tid):"NULL")+","+(pid?std::to_string(pid):"NULL")+","+sqlnum(jint(time,"elapsed"))+","+sqlnum(jint(time,"extra"))+","+db.quote(jstr(x,"type"))+","+db.quote(jstr(x,"detail"))+")");}}
void importApiHistory(Database& db,const Settings& settings,const League& league,bool detail,int budget,Job& job){
    if(league.provider!=1)throw std::runtime_error("Select a league from the API-Football catalog.");Api api(settings,job,budget);int year=std::stoi(today().substr(0,4));int imported=0;
    for(int season=year-5;season<=year&&api.room();++season){int page=1,pages=1;do{auto j=api.get("fixtures?league="+league.key+"&season="+std::to_string(season)+(page>1?"&page="+std::to_string(page):""));db.exec("START TRANSACTION");try{for(auto& x:j["response"]){job.check();Match m;auto fixture=x["fixture"],teams=x["teams"];m.external=jint(fixture,"id");m.date=jstr(fixture,"date").substr(0,10);if(m.date<yearsAgo(5))continue;dayNumber(m.date);m.league=league.id;m.season=season;m.status=jstr(fixture["status"],"short");m.home=db.team(1,std::to_string(jint(teams["home"],"id")),jstr(teams["home"],"name"));m.away=db.team(1,std::to_string(jint(teams["away"],"id")),jstr(teams["away"],"name"));if(x.contains("score")&&x["score"].contains("fulltime")){m.h[0]=jint(x["score"]["fulltime"],"home");m.a[0]=jint(x["score"]["fulltime"],"away");}if(m.status!="FT"&&m.status!="AET"&&m.status!="PEN")m.h[0]=m.a[0]=-1;db.upsertMatch(m,1);++imported;}db.exec("COMMIT");}catch(...){db.exec("ROLLBACK");throw;}pages=j.contains("paging")?jint(j["paging"],"total",1):1;++page;}while(page<=pages&&api.room());}
    if(detail){auto matches=db.matches(league.id);std::stable_sort(matches.begin(),matches.end(),[](auto&a,auto&b){return a.date>b.date;});int processed=0;for(auto&m:matches){job.check();if(!m.external)continue;if(m.date>addDays(today(),14))continue;for(int k=0;k<5&&api.room();++k){if(m.details&(1<<k))continue;if(m.h[0]<0&&k!=1&&k!=4)continue;const char* endpoint[]={"fixtures/statistics","fixtures/lineups","fixtures/players","fixtures/events","injuries"};auto j=api.get(std::string(endpoint[k])+"?fixture="+std::to_string(m.external));db.exec("START TRANSACTION");try{
                    if(k==0)statistics(db,m,j["response"]);else if(k==1)lineups(db,m.id,j["response"]);else if(k==2)players(db,m.id,j["response"]);else if(k==3)events(db,m.id,j["response"]);else for(auto& x:j["response"]){int pid=apiPlayer(db,x["player"]),tid=db.team(1,std::to_string(jint(x["team"],"id")),jstr(x["team"],"name"));if(pid)db.exec("REPLACE INTO injury(fixture_id,player_id,team_id,reason,type) VALUES("+std::to_string(m.id)+","+std::to_string(pid)+","+std::to_string(tid)+","+db.quote(jstr(x["player"],"reason"))+","+db.quote(jstr(x["player"],"type"))+")");}
                    // Future lineups/injuries may change, so do not permanently mark them complete.
                    if(m.h[0]>=0)db.exec("UPDATE fixture SET detail_flags=detail_flags | "+std::to_string(1<<k)+" WHERE id="+std::to_string(m.id));db.exec("COMMIT");
                }catch(...){db.exec("ROLLBACK");throw;}}
            job.progress=double(++processed)/std::max(size_t(1),matches.size());if(!api.room())break;}}
    job.message("API: "+std::to_string(imported)+" fixtures refreshed. "+(api.room()?"Import complete for available coverage.":"Request budget reached; rerun to resume remaining details."));
}
void refreshNewsSelection(Database& db){std::map<int,std::string> names;for(auto& row:db.query("SELECT id,name FROM team"))names[std::stoi(*row[0])]=*row[1];for(auto& n:db.news()){if(n.category=="Manual"||n.url.starts_with("demo://"))continue;selectRelevantNews(n,names[n.team]);
    if(n.decision==0&&!n.reviewed){std::tm date{};std::istringstream stamp(n.published);stamp.imbue(std::locale::classic());stamp>>std::get_time(&date,"%a, %d %b %Y %H:%M:%S");
      if(stamp.fail()){n.selected=false;n.reason="Unknown publication date; review manually";}
      else{char day[16];snprintf(day,sizeof(day),"%04d-%02d-%02d",date.tm_year+1900,date.tm_mon+1,date.tm_mday);n.expires=addDays(day,7);if(n.expires<today()||std::string(day)>today()){n.selected=false;n.reason="Outside the current news window";}}
    }db.saveNews(n);}}
void searchNews(Database& db,const Team& team,const std::string& query,const std::string& feed,Job& job){
    if(!team.id)throw std::runtime_error("Select a team first");job.message("Searching public news RSS");std::string url=feed.empty()?"https://news.google.com/rss/search?q="+urlEncode("\""+team.name+"\" (injury OR suspended OR suspension OR \"red card\" OR \"ruled out\") "+(query=="injury suspension red card"?"":query)+" when:7d")+"&hl=en-US&gl=US&ceid=US:en":feed;auto body=httpGet(url);pugi::xml_document doc;if(!doc.load_buffer(body.data(),body.size()))throw std::runtime_error("Feed was not valid RSS/XML. You can enter a club RSS URL.");int count=0;
    for(auto node:doc.select_nodes("//item")){job.check();auto item=node.node();News n;n.team=team.id;n.title=item.child_value("title");n.url=item.child_value("link");n.published=item.child_value("pubDate");if(n.title.empty()||!n.url.starts_with("http"))continue;
        std::string lower=n.title;std::transform(lower.begin(),lower.end(),lower.begin(),[](unsigned char c){return char(std::tolower(c));});n.category=lower.find("injur")!=std::string::npos?"Injury":lower.find("suspend")!=std::string::npos||lower.find("red card")!=std::string::npos?"Suspension/cards":"Other";
        std::tm tm{};std::istringstream in(n.published);in.imbue(std::locale::classic());in>>std::get_time(&tm,"%a, %d %b %Y %H:%M:%S");if(!in.fail()){char d[16];snprintf(d,sizeof(d),"%04d-%02d-%02d",tm.tm_year+1900,tm.tm_mon+1,tm.tm_mday);if(std::string(d)<addDays(today(),-7))continue;}
        n.expires=addDays(today(),7);std::tm date{};std::istringstream stamp(n.published);stamp.imbue(std::locale::classic());stamp>>std::get_time(&date,"%a, %d %b %Y %H:%M:%S");if(!stamp.fail()){char d[16];snprintf(d,sizeof(d),"%04d-%02d-%02d",date.tm_year+1900,date.tm_mon+1,date.tm_mday);if(std::string(d)>today())continue;n.expires=addDays(d,7);}selectRelevantNews(n,team.name);if(stamp.fail()){n.selected=false;n.reason="Unknown publication date; review manually";}db.saveNews(n);if(++count>=50)break;}
    job.progress=1;job.message(std::to_string(count)+" news items stored. Availability headlines are automatically selected; confirm or reject them in News & availability.");
}
